$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-new-tabs-g2.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({status:'hard_timeout'}));process.exit(0)},11500);
const arr=await(await fetch('http://127.0.0.1:17447/json/list')).json();
const out=[];
for(const o of [{"id":"EF27777D4E798E704D04D5D474887AFA","model":"15pm"},{"id":"B025E9E07C7426B014912EF6ABB37AB5","model":"16pm"}]){
 const t=arr.find(x=>x.id===o.id);
 if(!t){out.push({model:o.model,error:'missing'});continue}
 const w=new WebSocket(t.webSocketDebuggerUrl);
 const result=await Promise.race([new Promise(resolve=>{
 w.addEventListener('open',()=>w.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:"(()=>({title:document.title,count:document.querySelectorAll('[data-marker=\"item\"]').length,first:document.querySelector('[data-marker=\"item\"] h3')?.textContent?.trim().slice(0,130)||''}))()",returnByValue:true}})),{once:true});
 w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(z.id===1)resolve(z.result?.result?.value||{error:z.error?.message||z.result?.exceptionDetails?.text})});
 w.addEventListener('error',()=>resolve({error:'ws_error'}),{once:true})
 }),new Promise(ok=>setTimeout(()=>ok({error:'tab_timeout'}),4500))]);
 out.push({model:o.model,result});w.close();
}
console.log(JSON.stringify(out));process.exit(0);
'@,[System.Text.UTF8Encoding]::new($false))
